      "code_excerpt": "// PRIMARY: crates/consensus/common/src/validation.rs:validate_against_parent_gas_limit (lines 352-393)\npub fn validate_against_parent_gas_limit<H, ChainSpec>(\n    header: &SealedHeader<H>,\n    parent: &SealedHeader<H>,\n    chain_spec: &ChainSpec,\n) -> Result<(), ConsensusError> {\n    // Check for an increase in gas limit beyond the allowed threshold.\n    if header.gas_limit() > parent_gas_limit {\n        if header.gas_limit() - parent_gas_limit >= parent_gas_limit / GAS_LIMIT_BOUND_DIVISOR {\n            return Err(ConsensusError::GasLimitInvalidIncrease { ... })\n        }\n    }\n    // Check for a decrease in gas limit beyond the allowed threshold.\n    else if parent_gas_limit - header.gas_limit() >= parent_gas_limit / GAS_LIMIT_BOUND_DIVISOR {\n        return Err(ConsensusError::GasLimitInvalidDecrease { ... })\n    }\n    // GAS_LIMIT_BOUND_DIVISOR = 1024\n}"
